// Everything the hook writer needs, from one project row — and the rules it
// must obey, which are the SAME rules Voice Mode gives the scripting run
// (a second copy, kept in lockstep by hand: change one, change both).
const row = $('HR Load').first().json || {};
const body = ($('Hook Regen Webhook').first().json || {}).body || {};
if (!row.id) throw new Error('hook-regen: project not found: ' + String(body.project_id || ''));

let opts = row.editing_options;
if (typeof opts === 'string') { try { opts = JSON.parse(opts); } catch (e) { opts = {}; } }
opts = (opts && typeof opts === 'object') ? opts : {};
let bible = {};
try { bible = JSON.parse(row.story_bible || '{}') || {}; } catch (e) { bible = {}; }
const chapters = (Array.isArray(row.chapters) ? row.chapters : []).filter((c) => Number(c.ordinal) > 0);
if (!chapters.length) throw new Error('hook-regen: this film has no chapters yet — the hook is written with the script, not before it.');
const evidence = Array.isArray(row.evidence) ? row.evidence : [];
const genre = (row.genre && typeof row.genre === 'object') ? row.genre : {};

const category = String(opts.category || '');
const cinematic = category === 'cinematic';
const kids = category === 'kids';
const HOOK_STYLES = ['teaser', 'question', 'figure', 'slate', 'action', 'cliffhanger'];
const SILENT = ['slate', 'action', 'cliffhanger'];
const wanted = String(body.hook_style || opts.hookStyle || '').trim().toLowerCase();
let allowed = HOOK_STYLES.includes(wanted) ? [wanted] : HOOK_STYLES.slice();
if (cinematic) allowed = allowed.filter((s) => SILENT.includes(s));
if (kids) allowed = allowed.filter((s) => ['teaser', 'question', 'slate'].includes(s));
if (!allowed.length) allowed = cinematic ? ['action'] : ['teaser'];
const forced = allowed.length === 1;

const DEFS = {
  teaser: 'TEASER — 3 to 5 SPOKEN beats of 2-10 words each, one shot per beat. The most dramatic stretch of the story told like a trailer: present tense, concrete, each beat a step further in, and NEVER the outcome — the viewer must not learn how it ends. Example shape for a heist story: "One student. / A bank with three vaults. / Past the guards, alone. / Out with the money, and nobody suspects him." card stays empty.',
  question: 'QUESTION — 1 or 2 SPOKEN beats (3-12 words each) plus card.line1 = ONE question on screen, 3-12 words, ending with "?", that the film answers. card.line2 and card.source empty.',
  figure: 'FIGURE — 1 or 2 SPOKEN beats plus card.line1 = ONE number the film states (a year, a sum, a count), copied EXACTLY as the narration or the research pack writes it — never a number you computed or remembered; card.line2 = what it measures, at most 8 words; card.source = the evidence ref (E1..E20) when it comes from the research pack, else "".',
  slate: 'SLATE — exactly 1 SILENT shot note (8-25 words): the establishing frame of the story\'s main location as the bible describes it, no person near the camera, calm, with empty space in the centre of the frame for a title. card.line1 = the PLACE (at most 6 words), card.line2 = the DATE or time as the story states it (at most 6 words; leave "" if the story never states one — do not invent a date). Nothing is spoken.',
  action: 'ACTION — 2 or 3 SILENT shot notes (8-25 words each): the climax IN MOTION — what the protagonist does at the peak, each note one concrete visible action with its sound implied, no faces close to camera. Nothing is spoken; the story starts right after.',
  cliffhanger: 'CLIFFHANGER — 2 or 3 SILENT shot notes (8-25 words each): the moment BEFORE the catastrophe or the turn, tension rising shot by shot, ending on the frame just before the outcome — never the outcome itself. Nothing is spoken; the film then starts from the beginning.',
};
const styleRules = '\nHOOK STYLE. ' + (forced
  ? 'The producer chose the style ' + allowed[0].toUpperCase() + ' — use it and no other.'
  : 'Choose the ONE style that fits this story best from the list below and name it in "style".') +
  '\n' + allowed.map((s) => '- ' + DEFS[s]).join('\n') +
  '\nA SPOKEN beat is a line the narrator says. A SILENT shot note is what the camera sees, present tense, never spoken — write it as a shot, not as prose.' +
  '\nThe hook may use only Story Bible characters and locations, and must not reveal how the story ends.\n';

const language = String(row.language || 'English');
const chaptersJson = JSON.stringify(chapters.map((c) => ({ chapter_number: c.ordinal, chapter_title: c.title, narrator_script: c.script })));
const claimsList = evidence.map((e) => e.ref + ': ' + String(e.claim || '') + ' | SOURCE: ' + String(e.source || '') + (e.date ? ' | DATE: ' + e.date : '')).join('\n');

const system = 'You are a hook writer for ' + String(genre.format || 'documentary') + ' videos. Viewers decide in the FIRST SECONDS whether to keep watching.\n\n' +
  'Write the OPENING HOOK — a short teaser of several fast shots BEFORE chapter 1 begins, in one of the styles defined below. It must create a gap the rest of the video pays off, without giving the ending away. This is a REWRITE asked for by the producer: the story, its chapters and its scenes already exist and stay exactly as they are — only the hook changes.\n\n' +
  (genre.hook_rule ? 'THE HOOK RULE FOR THIS GENRE — follow it exactly:\n' + genre.hook_rule + '\n\n' : '') +
  (genre.voice ? 'GENRE VOICE — the hook is spoken in the same voice as the rest of the narration:\n' + genre.voice + '\n\n' : '') +
  'Rules:' + styleRules +
  '1. style: the style you used, exactly one of the names listed above, lower-case.\n' +
  '2. beats: an array with one string per SHOT, in order — spoken lines for a spoken style, shot notes for a silent one, as the style defines. Written in ' + language + ' for spoken beats; shot notes in ENGLISH. Concrete and specific to THIS story — no clichés ("What if I told you", "You won\'t believe"), no vague drama, no summary of the whole film. Each beat is its own shot, so each must be a different picture.\n' +
  '3. NEVER reveal the ending or the final turn. The hook opens a gap; chapter 1 onward closes it. A number, name or event that appears only in the last chapter does not belong in the hook.\n' +
  '4. card: {line1, line2, source} exactly as the style defines; every field you do not use is "".\n' +
  '5. hook_summary: in ENGLISH, 2-3 sentences describing what the viewer SEES across the hook\'s shots (use only Story Bible characters/locations).\n' +
  (cinematic ? '\nTHIS FILM HAS NO NARRATION: nothing in the hook is spoken either. Only the SILENT hook styles are available — every beat you write is a shot note the camera performs, never a line a voice reads.\n' : '') +
  (kids && !cinematic ? '\nKIDS STORY: open like a storyteller inviting a child in — warm, curious, direct — never dramatic or ominous.\n' : '') +
  '\nReturn ONLY a raw JSON object: {"style": "...", "beats": ["..."], "card": {"line1": "", "line2": "", "source": ""}, "hook_summary": "..."}. No markdown.';

const user = 'THE FULL NARRATION (chapters JSON — the hook must set up THIS exact story, without spoiling its ending):\n' + chaptersJson +
  '\n\nSTORY BIBLE (the film\'s locked world — the hook\'s visuals may use ONLY these characters and locations):\n' + JSON.stringify(bible) +
  (claimsList ? '\n\nRESEARCH PACK (sourced claims, by ref):\n' + claimsList : '') +
  '\n\nTema: ' + String(row.name || '') + '\nTonalitate: ' + String(row.tone || '') + '\nLanguage: ' + language;

const payload = {
  model: 'gpt-5.4',
  response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
};
return [{ json: {
  payload, allowed, forced, wanted: HOOK_STYLES.includes(wanted) ? wanted : 'auto', silentStyles: SILENT,
  projectId: row.id, language, style: String(row.style || ''), tone: String(row.tone || ''),
  category, cinematic, kids, bible, chapters, evidenceText: JSON.stringify(evidence),
  hookChapterId: ((Array.isArray(row.chapters) ? row.chapters : []).find((c) => Number(c.ordinal) === 0) || {}).id || '',
  oldHookSceneIds: Array.isArray(row.hook_scene_ids) ? row.hook_scene_ids : [],
  aspect: String(row.aspect || '16:9'),
} }];

// The same measurable rules Hook Guard applies in the scripting run — beat
// counts, words per beat, the card fields a style needs, a figure or a date
// the film actually states, no number that appears only in the last chapter.
// At most MAX_RETRIES rounds with the reason, then accept anyway: a wrong
// hook still makes a film, and nothing here may strand the producer.
const prep = $('HR Prep').first().json;
const MAX_RETRIES = 2;
const attempt = $runIndex + 1;
const wc = (s) => String(s || '').trim().split(/\s+/).filter(Boolean).length;

let raw = String((((($json.choices || [])[0] || {}).message || {}).content) || '').trim();
raw = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let hook = {};
try { hook = JSON.parse(raw) || {}; } catch (e) { hook = {}; }

const allowed = prep.allowed;
const SILENT = prep.silentStyles;
const style = String(hook.style || '').trim().toLowerCase();
const beats = (Array.isArray(hook.beats) ? hook.beats : []).map((b) => String(b || '').replace(/\s+/g, ' ').trim()).filter(Boolean);
const card = hook.card && typeof hook.card === 'object' ? hook.card : {};
const line1 = String(card.line1 || '').trim();
const line2 = String(card.line2 || '').trim();
const source = String(card.source || '').trim();
const silent = SILENT.includes(style);
const SHAPE = { teaser: [3, 5, 2, 10], question: [1, 2, 3, 12], figure: [1, 2, 3, 12], slate: [1, 1, 8, 25], action: [2, 3, 8, 25], cliffhanger: [2, 3, 8, 25] };

const problems = [];
if (!raw || !Object.keys(hook).length) problems.push('the answer was not a JSON object');
if (!allowed.includes(style)) problems.push('style must be one of: ' + allowed.join(', ') + (style ? ' (got "' + style + '")' : ' (none given)'));
const shape = SHAPE[style] || SHAPE.teaser;
if (beats.length < shape[0] || beats.length > shape[1]) problems.push('beats: ' + beats.length + ' given, this style needs ' + (shape[0] === shape[1] ? shape[0] : shape[0] + '-' + shape[1]));
beats.forEach((b, i) => { const w = wc(b); if (w < shape[2] || w > shape[3]) problems.push('beat ' + (i + 1) + ' is ' + w + ' words; each beat of this style is ' + shape[2] + '-' + shape[3]); });

const chapters = prep.chapters || [];
const filmText = chapters.map((c) => String(c.script || '')).join('\n');
const evidenceText = String(prep.evidenceText || '');
const digits = (s, min) => (String(s || '').match(/\d[\d.,\s]*\d|\d/g) || []).map((n) => n.replace(/[^\d]/g, '')).filter((n) => n.length >= (min || 1));
const corpusDigits = new Set(digits(filmText).concat(digits(evidenceText)));
if (style === 'question') {
  if (wc(line1) < 3 || wc(line1) > 12 || !/\?\s*$/.test(line1)) problems.push('card.line1 must be one on-screen question of 3-12 words ending with "?"');
}
if (style === 'figure') {
  const nums = digits(line1);
  if (!nums.length) problems.push('card.line1 must contain the figure itself (a number)');
  else if (!nums.every((n) => corpusDigits.has(n))) problems.push('card.line1 shows "' + line1 + '", a figure the narration and the research never state — copy a number the film actually says, exactly as written');
  if (wc(line2) > 8) problems.push('card.line2 is ' + wc(line2) + ' words; at most 8');
  if (source && !new RegExp('\\b' + source.replace(/[^A-Za-z0-9]/g, '') + '\\b').test(evidenceText)) problems.push('card.source names ' + source + ', which is not in the research pack — leave it "" unless the figure comes from a listed claim');
}
if (style === 'slate') {
  if (!line1 || wc(line1) > 6) problems.push('card.line1 must name the PLACE in at most 6 words');
  if (wc(line2) > 6) problems.push('card.line2 must be the date or time in at most 6 words, or ""');
}
if (silent && beats.some((b) => /^\s*\[(NARRATOR|CHARACTER)/i.test(b))) problems.push('a silent style carries no speaker tags — beats are shot notes');
if (chapters.length > 1) {
  const lastDigits = new Set(digits(chapters[chapters.length - 1].script, 2));
  const earlier = new Set(digits(chapters.slice(0, -1).map((c) => c.script).join('\n'), 2));
  const leaked = digits(beats.join(' ') + ' ' + line1 + ' ' + line2, 2).filter((n) => lastDigits.has(n) && !earlier.has(n));
  if (leaked.length) problems.push('the hook states ' + leaked.join(', ') + ', which appears only in the LAST chapter — that is the ending; take it out');
}

if (problems.length && attempt <= MAX_RETRIES) {
  console.log('HOOK REGEN guard retry ' + attempt + '/' + MAX_RETRIES + ' [' + style + ']: ' + problems.join(' | '));
  const payload = JSON.parse(JSON.stringify(prep.payload));
  payload.messages.push({ role: 'user', content: 'THE PREVIOUS ATTEMPT WAS REJECTED — ' + problems.join('; ') + '. Keep the same story, fix exactly these points. Return ONLY the JSON object.' });
  return [{ json: { retry: true, payload, attempt } }];
}
if (!beats.length) throw new Error('hook-regen: the model returned no beats after ' + attempt + ' attempts');
let finalStyle = style;
if (!allowed.includes(finalStyle)) { console.log('HOOK REGEN style "' + finalStyle + '" not allowed here, using ' + allowed[0]); finalStyle = allowed[0]; }
if (problems.length) console.log('HOOK REGEN accepting after ' + MAX_RETRIES + ' retries [' + finalStyle + ']: ' + problems.join(' | '));
else console.log('HOOK REGEN guard ok [' + finalStyle + ']: ' + beats.length + ' beats');
const finalSilent = SILENT.includes(finalStyle);
return [{ json: {
  retry: false,
  hook: {
    style: finalStyle,
    silent: finalSilent,
    beats,
    card: { line1, line2, source },
    summary: String(hook.hook_summary || '').trim(),
    lines: beats.map((b) => (finalSilent ? '[SILENT] ' : '') + b.replace(/^\s*\[SILENT\]\s*/i, '')),
  },
} }];

// One shot per beat — the hook chapter's rules from Voice Mode's
// hookSegmentRules and the segmenter's image/motion/continuity rules, in a
// second copy kept in lockstep by hand. The scripting run's segmenter is the
// original; this asks for the same fields so the scenes it writes are
// indistinguishable from the ones Save scenes To Airtable1 writes.
//
// 2026-09-13 — THIS COPY IS THE ONE THAT WROTE THE BROKEN CLIP. The café
// film's failing shot was a HOOK scene, so Claude Scripting's rule 6 never
// touched it: Hook Regen writes the hook's scenes from the rules below, and
// they were still the old wording. Rule 5 here is now the same instruction as
// the segmenter's rule 6 (`db/port/motion-permanence/paste/rule6.txt`),
// sentence for sentence, with three deliberate hook-only differences flagged
// at the line itself.
//
// What changed, in the order the producer hit them on screen:
//  - ONE ACTION, NOT A SEQUENCE. Nothing here forbade chaining verbs, so a
//    hook beat came back as "reaches ... strips off ... pivots back toward the
//    swinging door" — three shots asked for in one. Veo fills the eight
//    seconds by performing the first action twice, losing the held object, and
//    walking the subject out of frame and back.
//  - OBJECT PERMANENCE. Nothing said that what a character picks up stays in
//    their hands, and an object that is merely picked up is put down again or
//    vanishes roughly half the time.
//  - AMBIENT MOTION IS NOT FREE. The old rule 5 handed the model
//    "ambient/atmospheric motion only", which reads as a standing order to
//    invent movement, and in a still indoor room the model invents wind: the
//    papers taped to the fridge flapped, and the fridge door and the prep
//    table moved with nobody touching them. Motion is now allowed only where
//    something in frame CAUSES it, indoors there is no weather, and nothing at
//    all is written when nothing causes motion.
//  - NO MOTION ADJECTIVE ON A PROP. "the swinging door" makes Veo swing the
//    door. Write "the door".
//  - THE NEGATIVE IS A BARE NOUN LIST NOW. The old appended clause was eleven
//    "no X" phrases; Google's own Veo guidance is explicit that instructive
//    negation ("no walls", "don't show walls") makes the model render the very
//    thing it names — which is how we came to ask, in the positive prompt, for
//    a subject that "appears, disappears, duplicates".
//  - "Everything else that moves travels the SAME way" is GONE. It is the same
//    sentence round one removed from the submit tail: it forbids the crossings
//    and oncoming traffic a teaser legitimately wants, and a hook is exactly
//    where those shots live.
//
// Note what happens to the appended "Negative:" clause downstream: HR Apply
// stores this prompt in `Video Scenă URL`, and Media Generation's
// `Current Scene`, `Submit Video Regen` and `End Frame Prompt` all SPLIT that
// field on /\s*Negative:\s*/i and keep only the half before it, then append
// their own canonical tail. So the clause below is what the producer reads in
// the site's textarea, not what Veo is sent — and if the two wordings drift
// apart, the textarea starts lying about the film. Grep for "Negative:" to
// find every copy; they must all move together.
const prep = $('HR Prep').first().json;
const hook = $json.hook;
const lines = hook.lines.map((l, i) => (i + 1) + '. ' + l).join('\n');
const style = prep.style || '';
const tone = prep.tone || '';

const system = 'Return ONLY a raw JSON object {"scenes": [...]}. No intro, no markdown.\n\n' +
  'You are a film editor and storyboard artist turning the OPENING TEASER of a film into shots. Each numbered line below is exactly ONE shot; output EXACTLY ' + hook.lines.length + ' scenes, in order, one per line.\n\n' +
  'THIS IS THE HOOK CHAPTER — the film\'s opening teaser, cut FAST. Every numbered line is one SHOT of 2-4 seconds, not an 8-second scene:\n' +
  '(a) scene_duration_seconds is 3 for every shot (6 for a shot whose line describes an empty establishing frame with room for a title).\n' +
  '(b) Composition for a shot that lasts three seconds: ONE strong subject, high contrast, dramatic light, tight or extreme framing — the kind of frame a trailer cuts to. No wide busy scenes that need time to read.\n' +
  '(c) video_motion_prompt: ONE decisive move that reads in a second — a fast push-in, a whip-pan, a hard tracking shot, a crash-zoom — and ONE clear action. Energy over subtlety. Rule 5 governs the rest of the sentence and it bites hardest here: a three-second shot has room for one gesture and nothing else.\n' +
  '(d) A line starting with [SILENT] is a shot note, not narration: copy it VERBATIM as narrator_text (keep the [SILENT] prefix), and build the image and the motion from what it describes. Nothing in it is spoken.\n' +
  '(e) A line describing an establishing frame with space for a title: the image is wide, static-feeling, nobody near the camera, the centre of the frame uncluttered; the motion is a slow, steady CAMERA drift only, and everything inside the frame holds still.\n' +
  '(f) Shots must differ hard from one another (location, subject, scale) — a teaser that shows the same frame three times is not a teaser.\n\n' +
  'CRITICAL OUTPUT HYGIENE: image_prompt and video_motion_prompt are sent VERBATIM to an image/video model. NEVER write rule labels or scaffolding words — no "visual_description", "bible", "[shot type]" or any bracketed placeholder. Flowing prose only.\n\n' +
  'CONTENT SAFETY — absolute for image_prompt and video_motion_prompt: (a) NO visible minors — imply a child off-screen (a small shoe, an empty swing); crowds are "adult men and women". (b) NO real, named or recognizable people — generic descriptions with "no resemblance to any real person". (c) NO graphic violence, gore, wounds or corpses — imply through aftermath, shadows, reactions. A prompt that breaks these gets the shot rejected.\n\n' +
  'Rules:\n' +
  '1. narrator_text: copy the numbered line, character for character (keep a [SILENT] prefix).\n' +
  '2. Use ONLY characters/locations from the STORY BIBLE and weave their full physical description (age, hair, face, exact clothing, colours) into every image prompt where they appear. Write the light INTO each image_prompt (hour, weather, quality of light, where the shadows fall).\n' +
  '3. image_prompt: ONE image per shot — the exact first frame the clip starts from. 60-90 words of flowing prose in English: shot type, the subject in full physical detail, the action frozen at the shot\'s opening instant, the location in detail, the lighting, the colour palette, the lens/framing, ending with the aesthetic tags (' + style + ', ' + tone + ' tone, cinematic, photorealistic, 8k).\n' +
  '4. visual_scene_description: 1-2 sentences of what happens on screen during the shot; something visibly changes.\n' +
  // Rule 5 is Claude Scripting rule 6, verbatim, except for three hook-only
  // deviations: the shot is 2-4 seconds rather than 8, "the next scene" reads
  // "the next shot" because that is the unit this prompt works in, and rule 6's
  // (a)-(d) sublabels are flattened into prose to match the numbering already
  // used here. Every other sentence must stay character-identical to rule6.txt.
  '5. video_motion_prompt: the Veo prompt as flowing prose — camera movement, then subject, then action, then context, then style & ambiance, 25-45 words. ONE ACTION, NOT A SEQUENCE: the shot is two to four seconds, which is one gesture and no more — a reach, a turn, a pour, a step. If the beat wants three things to happen, choose the ONE that carries the story and let the rest be implied by the next shot. Never chain verbs with "then", "and then", or a comma list ("reaches, strips off the stack, and pivots to the door" is three shots, and asking for it in one produces a subject that teleports, drops what it is holding, and walks out and back to fill the time). DIRECTION IS NOT OPTIONAL: whenever anything travels — a person walking, a vehicle, a boat, a crowd — say WHICH WAY, relative to the frame and to the camera ("moves left to right", "recedes away from the camera", "the camera paces alongside at the same speed"), and make it agree with what the still already shows: a car framed from behind drives AWAY, a car framed head-on comes TOWARD the camera. IF THE SUBJECT HOLDS OR PICKS UP ANYTHING, say that it stays in their hands to the end of the shot — an object that is merely picked up is put down again, or vanishes, roughly half the time. Context: describe ONLY motion that something in the shot is actually causing, and name its cause. Steam rises because the machine is on; water ripples because the boat cut it; dust blows because there is wind outdoors. INDOORS THERE IS NO WEATHER — in a room, a kitchen, an office or a stockroom the air is still, and paper, cloth, curtains, hanging signs and loose sheets stay exactly as the still shows them. If nothing in the shot is causing motion, write nothing here: a still background is correct and costs nothing, while invented ambient motion is the single commonest way a clip goes wrong (a café stockroom came back with the papers taped to the fridge flapping in a wind that cannot exist indoors, because the prompt said "loose paper edges quiver"). EVERYTHING THE SUBJECT DOES NOT TOUCH HOLDS STILL: doors, drawers, lids, fridges and windows stay in the position the still shows them in, and only the subject\'s own hands move them. Never give a prop a motion word as a label — write "the door", never "the swinging door", because Veo animates the adjective. Style & ambiance: ' + style + ', ' + tone + ' mood, cinematic. Then append this exact clause at the end, and note that it is a NOUN LIST on purpose — Google\'s own Veo guidance is that instructive phrasing ("no walls", "don\'t show walls") makes the model render the very thing it names, so what is unwanted is listed as bare nouns and everything wanted is stated positively above: "Negative: on-screen text, subtitles, captions, watermark, logos, speech, lip movement, dialogue, music, extra people, duplicated subject, morphing, warping, reversed playback."\n' +
  '6. CONTINUITY FIELDS, read by CODE: location = the one bible location this shot is set in, spelled EXACTLY as the bible spells it ("" if nowhere in the bible); characters = every bible character visible, exact names (empty list if none); objects = every bible object visible, exact names; time_of_day = one word: dawn, morning, day, afternoon, dusk, night, overcast, storm, or interior.\n' +
  (prep.kids ? '\nKIDS STORY MODE — the film LOOKS like an animated children\'s film, never like photography: rounded, friendly proportions, no photorealistic humans; keep every movement gentle.\n' : '') +
  '\nEach scene object: scene_number (from 1), scene_duration_seconds, narrator_text, visual_scene_description, image_prompt, video_motion_prompt, location, characters, objects, time_of_day.';

const user = 'STORY BIBLE:\n' + JSON.stringify(prep.bible) +
  '\n\nWHAT THE VIEWER SEES ACROSS THE HOOK (the writer\'s own summary):\n' + (hook.summary || '(none)') +
  '\n\nTHE SHOTS, one per numbered line:\n' + lines;

return [{ json: { payload: { model: 'gpt-5.4', response_format: { type: 'json_object' }, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] }, hook } }];

// Turn the shots into the SQL that replaces the hook, one statement per item
// so HR Commit can run them inside one transaction: the old chapter-0 scenes
// go, the new ones are created through hov.at_create with exactly the fields
// Save scenes To Airtable1 writes, the hook chapter's script is rewritten,
// and the project's hookPlan is merged while hookRegen is cleared — the flag
// the site set before firing this run.
const prep = $('HR Prep').first().json;
const hook = $('HR Shots Prompt').first().json.hook;
let raw = String((((($json.choices || [])[0] || {}).message || {}).content) || '').trim();
raw = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let parsed = {};
try { parsed = JSON.parse(raw) || {}; } catch (e) { throw new Error('hook-regen: the shot writer did not return JSON'); }
const scenes = Array.isArray(parsed.scenes) ? parsed.scenes : (Array.isArray(parsed) ? parsed : []);
if (scenes.length !== hook.lines.length) throw new Error('hook-regen: asked for ' + hook.lines.length + ' shots, got ' + scenes.length);

// Canonicalise the continuity fields against the bible, diacritic-insensitive,
// as Validate Evidence Refs does; a name not in the bible is dropped.
const norm = (s) => String(s || '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().trim();
const names = (list) => (Array.isArray(list) ? list : []).map((e) => String((e && e.name) || '').trim()).filter(Boolean);
const bible = prep.bible || {};
const canon = (v, pool) => { const n = norm(v); const hit = pool.find((p) => norm(p) === n); return hit || ''; };
const locs = names(bible.locations), chars = names(bible.characters), objs = names(bible.objects);
const TOD = ['dawn', 'morning', 'day', 'afternoon', 'dusk', 'night', 'overcast', 'storm', 'interior'];

// Every literal is base64 and decoded by Postgres, and that is NOT tidiness —
// it is the only encoding that survives this node's own transaction.
//
